//------------------------------------------------------------------------------
//Callback Name: initialize_cb
//------------------------------------------------------------------------------
void TianFenXI::initialize_cb()
{
    try
    {
        group0 = dynamic_cast<NXOpen::BlockStyler::Group*>(theDialog->TopBlock()->FindBlock("group0"));
        selection0 = dynamic_cast<NXOpen::BlockStyler::SelectObject*>(theDialog->TopBlock()->FindBlock("selection0"));
        string0 = dynamic_cast<NXOpen::BlockStyler::StringBlock*>(theDialog->TopBlock()->FindBlock("string0"));
        toggle0 = dynamic_cast<NXOpen::BlockStyler::Toggle*>(theDialog->TopBlock()->FindBlock("toggle0"));
        string01 = dynamic_cast<NXOpen::BlockStyler::StringBlock*>(theDialog->TopBlock()->FindBlock("string01"));
        //------------------------------------------------------------------------------
        //Registration of StringBlock specific callbacks
        //------------------------------------------------------------------------------
        //string0->SetKeystrokeCallbackHandler(make_callback(this, &TianFenXI::KeystrokeCallbackHandler));
        
        //------------------------------------------------------------------------------
        ConfigureFaceSelectionBlock();
        LoadUiSettings();
        UpdateDeleteRVisibility();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
}

