void TianFenXI::dialogShown_cb()
{
    try
    {
        UpdateDeleteRVisibility();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
}

//------------------------------------------------------------------------------
//Callback Name: apply_cb
//------------------------------------------------------------------------------
int TianFenXI::apply_cb()
{
    int errorCode = 0;
    try
    {
        DebugLog("Apply clicked");
        PreviewSelectedFaceChain(true);
        DebugLog("Apply preview and middle plane creation done");
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

//------------------------------------------------------------------------------
//Callback Name: update_cb
//------------------------------------------------------------------------------
int TianFenXI::update_cb(NXOpen::BlockStyler::UIBlock* block)
{
    try
    {
        if(block == selection0)
        {
            if (updatingSelectionProgrammatically)
            {
                DebugLog("Selection update ignored: programmatic rewrite");
            }
            else
            {
                PreviewSelectedFaceChain();
            }
        }
        else if(block == string0)
        {
        //---------Enter your code here-----------
        }
        else if(block == toggle0)
        {
            UpdateDeleteRVisibility();
            SaveUiSettings();
        }
        else if(block == string01)
        {
            SaveUiSettings();
        }
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return 0;
}

//------------------------------------------------------------------------------
//Callback Name: ok_cb
//------------------------------------------------------------------------------
int TianFenXI::ok_cb()
{
    int errorCode = 0;
    try
    {
        errorCode = apply_cb();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        TianFenXI::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}
